    whenLow: 'Wenn T → 0',
    low: 'Niedrig',
    whenLowDesc: 'Division durch ein kleines T verstärkt die Unterschiede zwischen den Scores. Der höchste Logit dominiert exponentiell.',
    whenHigh: 'Wenn T → ∞',
    high: 'Hoch',
    whenHighDesc: 'Division durch ein großes T drückt alle Scores gegen null, sodass sie nach der Exponentialfunktion nahezu gleich werden.',
    truncationTitle: 'Temperatur im Zusammenspiel mit Top-p und Min-p',
    truncationBody: 'Die Temperatur formt die ganze Verteilung um. Abschneidende Sampler entfernen danach den unwahrscheinlichen Rest, bevor ein Token gezogen wird; die verbleibenden Wahrscheinlichkeiten werden neu normiert.',
    truncationTopP: 'Top-p (Nucleus Sampling) behält die kleinste Menge der wahrscheinlichsten Tokens, deren Wahrscheinlichkeiten zusammen p erreichen. Eine flache Verteilung braucht dafür viele Tokens, eine spitze nur wenige.',
    truncationMinP: 'Min-p behält jedes Token, dessen Wahrscheinlichkeit mindestens p_min mal der Wahrscheinlichkeit des wahrscheinlichsten Tokens beträgt. Die Schwelle folgt damit in jedem Schritt der Sicherheit des Modells.',
    truncationOrder: 'Die Reihenfolge zählt. Wird die Temperatur zuerst angewendet, flacht ein höheres T die Verteilung ab und lässt mehr Tokens in die Top-p-Menge. Wird sie zuletzt angewendet, entscheidet das Abschneiden auf der unskalierten Verteilung, und die Temperatur verteilt nur noch Wahrscheinlichkeit unter den verbliebenen Tokens um. Die Standard-Samplerkette von llama.cpp endet mit der Temperatur, nach Top-k, Top-p und Min-p; andere Bibliotheken ordnen die Schritte anders. Deshalb empfehlen Model Cards Kombinationen von Einstellungen statt einer einzelnen Temperatur.',
