    guidelinesExample: 'Beispiel: Qwen3 empfiehlt für den Thinking-Modus T = 0,6, Top-p = 0,95, Top-k = 20 und Min-p = 0 und warnt vor Greedy Decoding. Ein allgemeines Rezept wie „Mathe immer mit T = 0“ wäre für dieses Modell unpassend.',
