  // Attention page
  attention: {
    title: 'Attention',
    description: 'Nachrechnen, wie ein Token Informationen anderer Positionen mit Queries, Keys, Values und einer kausalen Maske kombiniert.',
    what: 'Eine gewichtete Kombination von Vektoren',
    body: 'Self-Attention bildet jede Eingangsrepräsentation mit gelernten Projektionen auf Query, Key und Value ab. Für eine Position wird ihre Query mit den Keys verglichen. Die Scores werden skaliert, gegebenenfalls maskiert und mit Softmax normiert. Diese Gewichte kombinieren die Values zu einem kontextuellen Vektor dieser Position.',
    parts: [
      { title: 'Query (Q)', body: 'Der projizierte Vektor, der für die gewählte Position die Keys bewertet.' },
      { title: 'Key (K)', body: 'Der projizierte Vektor jeder möglichen Bezugsposition. Ein Skalarprodukt vergleicht ihn mit der Query.' },
      { title: 'Value (V)', body: 'Die projizierte Information, die entsprechend dem Attention-Gewicht kombiniert wird. Der Key bestimmt ein Gewicht; der Value trägt zur Ausgabe bei.' },
    ],
    formula: 'Ein Head in Matrixschreibweise',
    formulaBody: 'Q und K haben die Breite dₖ. Ihre Skalarprodukte ergeben einen Score pro Query-Key-Paar. Die Skalierung mit √dₖ kontrolliert die Scoregröße. Softmax wird zeilenweise über erlaubte Keys berechnet. M enthält 0 für erlaubte und −∞ für maskierte Positionen.',
    sqrtTitle: 'Warum durch √dₖ teilen?',
    sqrtBody: 'Angenommen, die Komponenten von Query und Key sind unabhängig, mit Mittelwert 0 und Varianz 1. Das Skalarprodukt q · k = Σ qᵢkᵢ summiert dₖ solcher Produkte, hat also Mittelwert 0 und Varianz dₖ: Typische Scores wachsen mit breiteren Heads wie √dₖ. Große Abstände zwischen Scores treiben Softmax in Richtung einer One-Hot-Verteilung. Dann landet fast das ganze Gewicht auf einem Key, und die Gradienten für die übrigen Keys werden winzig. Die Division durch √dₖ bringt die Varianz unabhängig von der Head-Breite wieder auf etwa 1. Genau so argumentiert das ursprüngliche Transformer-Paper (Abschnitt 3.2.1, Fußnote 4).',
    sqrtCaveat: 'Das Argument betrifft die typische Größenordnung bei der Initialisierung. Trainierte Projektionen können trotzdem scharfe oder flache Attention-Muster erzeugen; die Skalierung sorgt nur für einen gutmütigen Ausgangspunkt.',
    sqrtCaption: 'Drei Keys mit rohen Scores +σ, 0 und −σ, wobei σ = √dₖ (die typische Größe aus dem Argument oben)',
    sqrtHeadDim: 'Head-Breite dₖ',
    sqrtRawStd: 'Typischer roher Score σ = √dₖ',
    sqrtUnscaled: 'Softmax ohne Skalierung',
    sqrtScaled: 'Softmax nach ÷ √dₖ',
    causal: 'Die Sichtbarkeit hängt von der Aufgabe ab',
    causalBody: 'Ein kausaler Decoder maskiert zukünftige Tokens, damit das Training die vorherzusagende Antwort nicht vorab verrät. Ein bidirektionaler Encoder kann Positionen auf beiden Seiten nutzen. Padding-Masken und andere Attention-Muster schränken die Sicht zusätzlich ein. Die Maske entscheidet über verfügbare Positionen; sie weist Heads keine sprachlichen Aufgaben zu.',
    cost: 'Was wächst quadratisch?',
    costBody: 'Vollständige dichte Attention berechnet beim Prefill n² Query-Key-Scores pro Head. Die Tabelle zählt Scores, keine gesamten Rechenoperationen. Skalarprodukte hängen zusätzlich von der Head-Breite ab; Modelle besitzen mehrere Heads und Layer. Der gezeigte Speicher betrifft nur eine vollständig gespeicherte Scorematrix mit zwei Bytes pro Element.',
    length: 'Sequenzlänge',
    pairs: 'Score-Einträge pro Head',
    storage: 'Naiver Score-Speicher',
    tokens: 'Tokens',
    flash: 'Speichereffiziente Attention',
    flashBody: 'FlashAttention organisiert exakte Attention in Blöcken. Dadurch sinken Transfers zwischen GPU-Speicherebenen, und die vollständige n × n-Scorematrix muss nicht gespeichert werden. Die dichte Attention-Rechnung wird dadurch nicht linear. Geschwindigkeits- und Speichergewinne hängen von Dimensionen, Präzision, Kernels und Hardware ab. Decoding eines einzelnen Tokens mit Cache hat eine andere Arbeitslast: Eine Query liest die vorhandenen Keys und Values.',
    interpretation: 'Attention-Gewichte allein erklären keine Antwort',
    interpretationBody: 'Die Gewichte beschreiben eine Operation in einem Head und Layer. Andere Heads, Value-Vektoren, Residualpfade und spätere Rechnungen beeinflussen die Antwort ebenfalls. Eine auffällige Verbindung belegt nicht, dass ein Wort die finale Entscheidung verursacht. Heads haben auch keine dauerhaft festgelegten Grammatik- oder Faktenaufgaben.',
    sources: 'Primärquellen',
    viz: {
      title: 'Einen Attention-Head ausrechnen',
      words: ['Die', 'Katze', 'schläft'],
      note: 'Das Beispiel enthält drei Wörter. Jedes Wort wird hier als ein Token behandelt. Eingangsvektoren und Projektionsgewichte sind für einfache Rechnungen gewählt und nicht aus Sprache gelernt. Die Attention-Gewichte und die Ausgabe werden daraus berechnet.',
      choose: '1. Das abfragende Token wählen',
      input: '2. Seinen Eingangsvektor x ändern',
      projections: 'Feste Projektionen (Zeilenvektoren: Q = XWQ, K = XWK, V = XWV)',
      mask: 'Kausale Maske: nur dieses und vorherige Tokens sind erlaubt',
      vectors: '3. Alle Token-Vektoren ansehen',
      token: 'Token',
      scores: '4. Skalarprodukt → Skalierung → Maske → Softmax',
      dot: 'Q · K',
      scaled: '÷ √2',
      weight: 'Attention-Gewicht',
      weighted: 'Gewicht × V',
      result: '5. Gewichtete Values summieren',
      reset: 'Vektoren zurücksetzen',
      explain: 'Die ausgewählte Query bewertet jeden Key. Danach wird durch √dₖ geteilt, verbotene Positionen werden auf −∞ gesetzt und Softmax wird auf die Zeile angewendet. Die Gewichte summieren sich zu 1; maskierte Positionen tragen null bei.',
      limit: 'Die Ausgabe ist ein kontextueller Vektor dieser Position, keine Next-Token-Wahrscheinlichkeit. Weitere Projektionen und Layer verarbeiten ihn. Ein großes Attention-Gewicht allein belegt weder Grammatik noch Wichtigkeit oder eine kausale Erklärung der Modellantwort.',
      bidirectional: 'Ohne Maske kann das ausgewählte Token auch spätere Positionen nutzen, wie bei bidirektionaler Encoder-Attention.',
    },
  },

