    arch_encoder_decoder_desc: 'Die ursprüngliche Architektur. Der Encoder verarbeitet die Eingabe bidirektional, der Decoder generiert Token für Token mit Cross-Attention. Verwendet für Übersetzung und Zusammenfassung.',
    arch_encoder_only_desc: 'Nutzt nur den Encoder mit bidirektionaler Attention. Hervorragend für Verständnisaufgaben wie Klassifikation und Named Entity Recognition. Nicht für Textgenerierung konzipiert.',
    arch_decoder_only_desc: 'Nutzt nur den Decoder mit kausaler Masked Attention. Die dominante Architektur moderner LLMs, da sie natürlich Textgenerierung modelliert und außergewöhnlich gut skaliert.',
