    apiExample: 'Beispiel für das 1536 × 1024 px große Referenzbild: Claude Opus 5.5 → 55 × 37 = 2.035 Token. GPT-5.4 „high“ → 48 × 32 = 1.536 Patches × 1,2 ≈ 1.844 Token.',
    apiCaveat: 'Abrechnungs-Patches sind Zählregeln und müssen nicht den internen Encoder-Patches entsprechen.',

    // Teil 2: Fehler
    partFailures: 'Teil 2: Wo Vision-Modelle scheitern',
    failuresIntro: 'Vision-Sprachmodelle beschreiben Fotos flüssig und scheitern trotzdem an Aufgaben, die ein Kind in einer Sekunde löst. Benchmarks, die genau solche Aufgaben prüfen, zeigen, wie groß die Lücke ist und woher sie kommt.',
    blindTitle: 'BlindTest: „Vision language models are blind“',
    blindDesc: 'Sieben triviale Geometrie-Aufgaben, etwa Schnittpunkte zweier Linien zählen oder entscheiden, ob sich zwei Kreise berühren. Die vier getesteten Modelle erreichten im Schnitt 58,07 %, das beste, Claude 3.5 Sonnet, 77,84 %. GPT-4o zählte die Schnittpunkte zweier einfacher Liniendiagramme nur in 41,61 % der Fälle richtig, Gemini-1.5 Pro überlappende Fünfecke nur in 9,16 %, oft mit der Antwort „5“ unabhängig von der echten Anzahl. Lineare Probes zeigten, dass der Vision-Encoder die nötige Information noch enthielt. Verloren geht sie erst, wenn das Sprachmodell sie in Worte übersetzt.',
    blinkTitle: 'BLINK: Wahrnehmung ohne Sprache',
    blinkDesc: '14 klassische Bildverarbeitungsaufgaben (relative Tiefe, visuelle Korrespondenz, Reflexion, Mehransichten …) als 3.807 Multiple-Choice-Fragen. Menschen: 95,70 %. GPT-4V: 51,26 %, Gemini Pro: 45,72 %, Raten: 38,09 %. Die Autoren argumentieren, dass sich diese Aufgaben nicht über Sprache vermitteln lassen: Man kann die Antwort nicht herbeibeschreiben.',
    countTitle: 'Zählen: CountBench und CountQA',
    countDesc: 'CountBench (2023) enthält 540 Bilder mit zwei bis zehn Exemplaren eines Objekts. Entstanden ist es, weil CLIP-artige Encoder Anzahlen kaum repräsentieren. CountQA (2025) nutzt über 1.500 dichte, unaufgeräumte Alltagsfotos; das beste von 15 Modellen erreichte 42,9 %, und die Genauigkeit sinkt mit steigender Anzahl.',

    // Demo 2: BlindTest-Aufgaben
    blindDemoTitle: 'Die BlindTest-Aufgaben selbst ausprobieren',
    blindDemoDesc: 'Jedes Testbild wird in deinem Browser erzeugt, die richtige Antwort wird aus der Geometrie berechnet. Die Balken zeigen die im Paper veröffentlichten Genauigkeiten dieser Modelle auf dem gesamten Aufgabensatz, nicht auf diesem konkreten Bild. Hier läuft kein Modell.',
    blindTaskLines: 'Linienschnitte',
    blindTaskCircles: 'Zwei Kreise',
