    benefit3: 'Datenfilterung',
    benefit3Desc: 'Große Tool-Ausgaben im Code verarbeiten und filtern, bevor sie das Modell erreichen.',
    benefit4: 'Nativer Kontrollfluss',
    benefit4Desc: 'Schleifen, Bedingungen und Fehlerbehandlung nutzen — das Modell schreibt echten Code, nicht nur JSON-Aufrufe.',
