    allowedCallersDesc: "In Anthropics API benennt allowed_callers den vorgesehenen direkten oder versionierten Code-Execution-Aufrufer. Das steuert die Toolnutzung, ersetzt aber keine Berechtigungsprüfung zur Laufzeit.",
    allowedCallersNote: 'Für Klarheit ist es am besten, pro Tool einen Modus zu wählen, anstatt beide zu aktivieren. Das gibt dem Modell klarere Hinweise zur Nutzung jedes Tools.',
