    codeExampleDesc: 'Der Agent schreibt Python, das über Regionen iteriert, ein Datenbank-Tool aufruft und Ergebnisse aggregiert — alles in einer Ausführung. Das Tool nimmt SQL-Text und Werte getrennt entgegen (sql + params), sodass der Datenbanktreiber die Region als Datum bindet. Auch vom Modell geschriebener Code ist nicht vertrauenswürdige Eingabe: Werte nie per String-Verkettung in SQL einsetzen.',
    controlNote: "Kontrollfall: Drei unabhängige Standard-Toolaufrufe lassen sich ebenfalls parallel ausführen. Ein Modellaufruf fordert sie an, ein weiterer fasst zusammen, genauso wie in diesem PTC-Beispiel. PTC kann zusätzlich Zwischendaten im Code filtern und aggregieren, sodass weniger in den Modellkontext gelangt.",
    boundaryNote: "Anthropic-API-Beispiel, geprüft im Oktober 2026. allowed_callers steuert die Aufrufwahl; erzwinge Zugriffsrechte in der Tool-Laufzeit, denn das Feld ist keine harte API-Sicherheitsgrenze.",
    keyTakeaways: 'Wichtige Erkenntnisse',
    takeaway1: 'Programmatische Tool-Aufrufe lassen Agenten Code schreiben, der Tools aufruft — ohne Roundtrips pro Tool.',
