    takeaway3: "Verwende die versionierten Aufruferkennungen des Anbieters und erzwinge Zugriffsrechte zur Laufzeit.",
    takeaway4: 'Ideal für Batch-Verarbeitung, bedingte Workflows, Datenfilterung und mehrstufige Tool-Ketten.',
    limitsTitle: 'Einschränkungen und Inkompatibilitäten',
    limitsDesc: 'Nicht jede Tool-Definition und nicht jede Request-Option lässt sich mit programmatischen Aufrufen kombinieren. Laut Anthropics Dokumentation (Oktober 2026) gilt:',
