    limitStrictDesc: 'Tools mit strict: true werden bei programmatischen Aufrufen nicht unterstützt. Prüfe Eingaben stattdessen im Toolhandler oder lass solche Tools nur direkt aufrufbar.',
    limitToolChoice: 'Kein erzwungener Code-Aufruf per tool_choice',
    limitToolChoiceDesc: 'Über tool_choice lässt sich nicht erzwingen, dass Claude ein bestimmtes Tool aus Code aufruft. Nennt tool_choice ein Tool, dessen allowed_callers kein "direct" enthält, lehnt die API die Anfrage mit 400 invalid_request_error ab.',
