    takeaway3: "APIs und Coding-Agenten verdichten inzwischen selbst (Anthropic-Compaction, OpenAI compact_threshold, Claude-Code-Auto-Compact). Auslöser und Zusammenfassungs-Prompt bleiben deine Entscheidung.",
