    pipelineDesc: 'Wähle eine Phase. Die Beispielantworten sind von Hand geschriebene Illustrationen typischen Verhaltens nach dieser Phase, keine Ausgaben eines bestimmten Modells. Echte Rezepte unterscheiden sich in der Reihenfolge und wiederholen Phasen oft.',
