        data: 'Gefilterter Webtext, Code, Bücher, wissenschaftliche Artikel, mehrsprachige Texte.',
        scale: '15–36 Billionen Tokens bei aktuellen offenen Modellen (Llama 3: über 15 Bio., Qwen3: etwa 36 Bio.). Mit Abstand der größte Rechenaufwand aller Phasen.',
        output: 'Was ist 17 × 25? Was ist 18 × 24? Was ist 19 × 24? …',
