    // Visualizer
    vizTitle: 'Temperatur & Verteilungsgl\u00E4ttung',
    vizSubtitle: 'Sehen Sie, wie Temperatur das Wissen des Lehrers f\u00FCr den Sch\u00FCler umformt',
