      lesson: "Probiere jeden Suchknopf aus: Jeder schließt seine eigene Lücke und lässt mindestens ein anderes Kriterium verletzt. Bei unterschiedlichen Basisraten kann die Suche nur wählen, welche Lücke sie schließt. Getrennte Schwellen pro Gruppe sind genau das, was Post-Processing-Verfahren tun (Hardt et al., 2016). Die Suche berücksichtigt nur Schwellen, die pro Gruppe mindestens einen richtig Positiven auswählen und mindestens einen Negativen ablehnen – sonst würden triviale Lösungen wie „alle auswählen“ gewinnen.",
