    intro: 'Warum Open Source in der KI wichtig ist',
    introDesc: "Unterscheide Open-Source-Software, offene Modellgewichte und vollständig offene KI-Systeme. Gewichtezugriff kann lokale Inferenz und Anpassung ermöglichen, garantiert aber keinen Zugang zu Trainingscode, Dateninformationen oder uneingeschränkten Nutzungsrechten. Die OSI-Definition benennt Freiheiten und benötigte Materialien zur Veränderung eines KI-Systems.",

    // Key Advantages Section
