    advantagesDesc: 'Open-Source-KI bietet einzigartige Vorteile, die geschlossene, proprietäre Systeme nicht bieten können.',

    advantage1Title: 'Transparenz',
    advantage1Desc: "Prüfe die tatsächlich veröffentlichten Artefakte: Code, Architektur, Gewichte und Dateninformationen. Sie ermöglichen unterschiedliche Prüfungen. Keines macht eine undurchsichtige neuronale Entscheidung automatisch erklärbar.",

    advantage2Title: 'Community-Innovation',
    advantage2Desc: "Wenn die Lizenzen es erlauben, können Menschen Fehlerkorrekturen, Werkzeuge und angepasste Modelle teilen. Eine funktionierende Community braucht Pflege, Dokumentation und Mitwirkende.",

    advantage3Title: 'Kosteneffizienz',
