    advantage4Title: 'Innovationsgeschwindigkeit',
    advantage4Desc: "Veröffentlichte Gewichte und Code können Fine-Tuning, Adapter und Integrationsexperimente ermöglichen. Welche Änderungen möglich sind, hängt von Artefakten, Lizenz und Rechenressourcen ab.",

    advantage5Title: 'Anbieterunabhängigkeit',
    advantage5Desc: "Lokale Gewichte und portable Werkzeuge können die Abhängigkeit von einer API verringern. Modellformate, Hardware-Backends und Anwendungsschnittstellen können dennoch Wechselkosten erzeugen.",

    advantage6Title: 'Sicherheit durch Auditing',
    advantage6Desc: "Verfügbarer Quellcode ermöglicht Audits. Sicherheit braucht weiterhin Reviews, Updates, gepflegte Abhängigkeiten und ein Bedrohungsmodell. Offenheit allein belegt nicht, dass Schwachstellen schneller gefunden werden.",

