    prefillDecodeExplain: "Prefill verarbeitet Prompt-Positionen innerhalb jeder Schicht zusammen. Decode ergänzt Tokens pro Anfrage nacheinander. Das Geschwindigkeitsverhältnis hängt von Modell, Hardware, Kontext und Batching ab. Es gibt keinen allgemeinen Multiplikator.",
