    tip1Title: 'Statischen Inhalt zuerst',
    tip1Desc: 'Cache-Matching funktioniert auf Präfixen. Platziere deinen System-Prompt und Few-Shot-Beispiele vor dynamischem Inhalt, damit das Präfix über Anfragen hinweg stabil bleibt.',
    tip2Title: 'Minimale Token-Anzahl beachten',
