      rlMethodDescs: ["Aktualisiert Schätzungen des erwarteten Returns für Zustands-Aktions-Paare.","Verändern Policy-Parameter mithilfe beobachteter Returns oder Advantage-Schätzungen.","Kombiniert eine Policy mit einer gelernten Wertschätzung.","Familien der Policy-Optimierung mit unterschiedlichen Schätzern und Update-Beschränkungen. Die Q-Learning-Demo implementiert diese Verfahren nicht."],
      imagePipelineNote: "Text-zu-Bild-Inferenz beginnt mit gezogenem latentem Rauschen. Ein VAE-Encoder wird bei der Vorbereitung von Bildlatenten für das Training oder für Bild-zu-Bild-Eingaben verwendet. Der VAE-Decoder übersetzt den fertig erzeugten Latent in Pixel.",
      imageSteps: ["Text → Konditionierung","Seed → latentes Rauschen","Denoiser + Scheduler → neuer Latent","VAE-Decoder → Pixel"],
      imageFlowNote: "Das ist ein Abhängigkeitsdiagramm und kein erzeugtes Bild. Halte Seed, Prompt, Auflösung, Modell und Scheduler fest, wenn du Guidance oder Schrittzahl vergleichst. Mehr Schritte verbessern die Qualität nicht zwangsläufig.",
    memoryTitle: "Speicherbudget mit sichtbaren Annahmen",
    memoryNote: "Gewichte verwenden alle Parameter, auch sämtliche MoE-Experten. Der KV-Speicher verwendet KV-Heads statt der Hidden-Dimension. Die Rechnung gilt für normale MHA/GQA/MQA-Caches. MLA, hybride rekurrente Schichten und die Runtime-Allokation brauchen modellspezifische Messungen.",
    memoryUnknown: "KV-Layout für dieses Preset unbekannt. Die Gewichtsgröße ist sichtbar; Gesamtspeicher und Eignung lassen sich nicht bestimmen. Trage verifizierte Standard-KV-Dimensionen ein, um weiterzurechnen.",
    memoryManual: "Manuelles Standard-KV-Layout",
    kvHeads: "KV-Heads",
    headDim: "Head-Dimension",
    batch: "Parallele Sequenzen",
    kvBytes: "Bytes pro KV-Element",
