    fits: "Innerhalb dieses Budgets",
    over: "Über diesem Budget",
    unitNote: "GiB = 2³⁰ Bytes; GB = 10⁹ Bytes. Gemeinsamer Speicher muss auch das Betriebssystem aufnehmen. Die Reserve ist eine veränderbare Annahme und kein gemessener Runtime-Verbrauch.",
    quantNote: "Die Q-Stufen sind beispielhafte Speicherbudgets: Bits × Overhead. Echte GGUF-Dateien mischen verschiedene Tensorformate. Verwende für die Hardware-Auswahl möglichst die gemessene Dateigröße.",
    transferTitle: "Warum die Speichergröße keine Geschwindigkeit vorhersagt",
    transferNote: "Ob ein Modell in den Speicher passt, prüft nur die Kapazität. Die Decode-Zeit hängt zusätzlich von aktiven Gewichten, KV-Verkehr, Rechenleistung, Kernels, Batchgröße und Platzierung ab. Es gibt keinen universellen GPU-Effizienzfaktor. Miss Prefill und Decode getrennt mit dem konkreten Modell und der Runtime.",
