    quantTitle: "Rotation und verlustbehaftete Quantisierung",
    quantToy: "Berechnetes Toy-Beispiel, keine TurboQuant-Implementierung. Eine orthogonale Rotation erhält die Norm. Ein gleichmäßiger skalarer Quantisierer rundet anschließend die Werte. Seine Umkehr stellt das Original nicht exakt wieder her. Verändere Winkel und Präzision und beobachte den Fehler.",
