    cacheNote: "Hypothetischer Tarif, kein Anbieterangebot. Eine Gruppe verwendet einen Prefix vor dem Ablauf erneut; jede neue Gruppe beginnt mit einem Write. TTL-Ablauf, Routing-Misses oder Prefix-Änderungen lassen sich durch weniger Anfragen pro Gruppe abbilden. Output-Kosten sind auf beiden Seiten ausgeschlossen.",
