    trainingNote: "Der Browser aktualisiert w und b tatsächlich per Gradientenabstieg auf dem mittleren quadratischen Fehler: Vorhersage = w·x + b. Blaue Punkte sind Trainingsdaten; orange Punkte gehören zur getrennten Validierung. Zielwerte und Anfangsgewichte sind fest, damit Läufe vergleichbar sind.",
