    noiseTitle: "Vorwärtsprozess mit berechnetem Rauschen",
    noiseNote: "xₜ = √ᾱ·x₀ + √(1−ᾱ)·ε, mit festem Seed und Gauß-Rauschen ε. Die Anzeige begrenzt die Zahlen auf den darstellbaren Farbbereich. Derselbe Seed macht Rauschstufen vergleichbar.",
    signal: "Signalstärke ᾱ",
    noiseLimit: "Zurückschieben blendet das gespeicherte Original ein. Das ist kein gelernter Rückwärts-Sampler. Bei der Generierung ist das Original unbekannt. Das Modell muss eine Entrauschungsrichtung aus dem verrauschten Zustand und der Konditionierung vorhersagen.",
    textTitle: "Maskieren nach Konfidenz: ein Rechenbeispiel",
    textNote: "Eine vorgegebene Kandidatentabelle steht für den Denoiser. Jeder Schritt berechnet diese Tabelle anhand des sichtbaren Kontexts neu und übernimmt die zwei sichersten maskierten Positionen. Die Konfidenz bestimmt die Auswahl. PAD-Positionen liegen außerhalb der Sequenz und nehmen nie teil.",
