    textSampler: "Dieses Beispiel verwendet unumkehrbares Aufdecken. Andere Sampler können Tokens erneut ändern. Die Wahrscheinlichkeiten sind vorgegebene Lernbeispiele und stammen nicht aus einem Sprachmodell.",
    worldTitle: "Vorhersagefehler wächst mit der Dauer",
    worldNote: "Durchgerechnetes Dynamikbeispiel: x(t) = v₀·t + ½a·t². Die Referenzbeschleunigung und der geschätzte Modellwert unterscheiden sich. Das ist eine analytische Toy-Welt, keine gemessene Leistung von Genie oder einem gelernten Modell.",
    worldVelocity: "Startgeschwindigkeit (m/s)",
    worldAcceleration: "Referenzbeschleunigung (m/s²)",
    worldEstimate: "Geschätzte Beschleunigung (m/s²)",
    worldHorizon: "Vorhersagedauer (s)",
    worldLimit: "Eine veränderte Schätzung verändert jeden vorhergesagten Zustand. Selbst ein kleiner Beschleunigungsfehler wächst hier quadratisch. Reale Weltmodelle haben zusätzlich unsichere Beobachtungen, Aktionen außerhalb ihrer Trainingsdaten und sich fortpflanzende Fehler.",
    chipTitle: "Vor dem Chip die Anforderungen klären",
    chipNote: "Das sind qualitative Prüffragen und keine Benchmark-Punkte. Die Chipfamilien überschneiden sich: Eine TPU ist ein ASIC; NPU bezeichnet unterschiedliche Beschleuniger. Ob etwas funktioniert, hängt vom konkreten Gerät und der unterstützten Runtime ab.",
    chipMemory: "Passen Modell und KV-Cache in den erreichbaren Speicher?",
    chipOperators: "Unterstützt der Compiler beziehungsweise die Runtime alle benötigten Operatoren und Präzisionen?",
