    chipCosts: "Was kosten Hardware, Hosting und Entwicklungsarbeit?",
    chipGpu: "GPU: breite Software-Unterstützung und flexible Kernels. Konkreten Speicher, Verbindungen und unterstützte Präzisionen prüfen.",
    chipTpu: "TPU: Tensorbeschleuniger mit einem bestimmten Compiler und verteilten System. Modellunterstützung und Zugang zur benötigten Generation prüfen.",
    chipNpu: "NPU: häufig für lokale Inferenz mit begrenzter Leistungsaufnahme gedacht. Speicher, Operatoren und Herstellerwerkzeuge können die Modellauswahl begrenzen.",
    chipAsic: "Eigener ASIC: spezialisiert Hardware auf eine Aufgabe. Entwicklungskosten, Stückzahl und Software entscheiden, ob sich das lohnt.",
    chipFpga: "FPGA: rekonfigurierbare Logik für eine eigene Pipeline. Operatoren abzubilden und Speicherbandbreite auszunutzen erfordert Entwicklungsarbeit.",
