    kvProjection: "K/V-Projektionen",
    kvAttentionNote: "Die Zähler zählen Paare von K/V-Projektionen pro Token, nicht sämtliche Attention-Operationen. Jede neue Query bewertet weiterhin die gecachten Keys. Die gezeigten Vektoren sind illustrative Beispiele.",
